from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    result = []  # Initialize an empty list to store separated parenthesis groups
    group = ""  # Initialize an empty string to store each group

    nesting_level = 0
    for char in paren_string:
        if char == '(':
            nesting_level += 1
            if nesting_level == 1:
                group += char
        elif char == ')':
            nesting_level -= 1
            if nesting_level == 0:
                group += char
                result.append(group)
                group = ""
        elif nesting_level > 0:
            group += char

    return result

