from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    stack = []
    result = []

    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            start = stack.pop()
            result.append(paren_string[start:i+1])  # Step 2: Identify and extract groups of nested parentheses using a stack data structure

    return result  # Step 3: Separate the extracted groups into individual strings and store them in a list

